from pathlib import Path
import sys
import cocotb
from cocotb.clock import Clock
from cocotb.triggers import ClockCycles, RisingEdge, Timer

sys.path.append(str(Path(__file__).parent.parent))

from cocotb_utils import CLK_PERIOD_NS, Runner, setup_runner

NOP = 0x00000013  # addi x0, x0, 0


def load_hex_file(filepath):
    """Parse hex file generated by objcopy -O verilog."""
    raw_bytes = []
    with open(filepath, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("//") or line.startswith("@"):
                continue
            parts = line.split()
            for part in parts:
                raw_bytes.append(int(part, 16))

    words = []
    for i in range(0, len(raw_bytes), 4):
        if i + 3 < len(raw_bytes):
            b0 = raw_bytes[i]
            b1 = raw_bytes[i + 1]
            b2 = raw_bytes[i + 2]
            b3 = raw_bytes[i + 3]
            word = (b3 << 24) | (b2 << 16) | (b1 << 8) | b0
            words.append(word)
    return words


def fill_mem(dut, words):
    """Fill IMem with words, padding remaining memory with NOPs."""
    imem_size = len(dut.u_ifu.IMem.imem.mem)
    for i in range(imem_size):
        dut.u_ifu.IMem.imem.mem[i].value = NOP
    for i, word in enumerate(words):
        dut.u_ifu.IMem.imem.mem[i].value = word
    dut._log.info(f"Successfully loaded {len(words)} instructions into IMem.")


def read_dmem(dut, byte_addr):
    """Read DMEM by byte address."""
    word_index = byte_addr // 4
    return int(dut.u_dmem.dmem.mem[word_index].value)


async def setup_dut(dut, start_pc=0):
    """Initialize clock, reset signals, and start program execution."""
    clock = Clock(dut.clk, CLK_PERIOD_NS, unit="ns")
    cocotb.start_soon(clock.start())
    dut.rst.value = 1
    dut.start.value = 0
    dut.program_address.value = start_pc
    await ClockCycles(dut.clk, 2)
    await Timer(1, unit="step")
    dut.rst.value = 0
    dut.start.value = 1
    await RisingEdge(dut.clk)
    await Timer(1, unit="step")
    dut.start.value = 0
    await RisingEdge(dut.clk)


@cocotb.test()
async def t_core_c_func_call_test(dut):
    """Test C function calls.

    Verifies:
    1. JAL instruction execution.
    2. JALR instruction return logic.
    3. Memory STORE operations.
    """
    TEST_DIR = Path(__file__).parent.parent
    hex_path = TEST_DIR / "build" / "jar" / "test.hex"

    words = load_hex_file(hex_path)
    fill_mem(dut, words)
    await setup_dut(dut, start_pc=0)

    max_cycles = 1000
    done = False
    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        done_flag = read_dmem(dut, 0x2000)
        if done_flag == 1:
            dut._log.info(f"Completion flag detected at cycle {cycle}.")
            done = True
            break

    assert done, "Program execution timed out. Possible issue with JAL/JALR or function return."

    result = read_dmem(dut, 0x1000)
    dut._log.info(f"Variable result = {result}")

    assert result == 123, f"Function call failed! Expected x=123, got actual={result}."
    dut._log.info("C function call test passed successfully!")


class TestCore_SV:
    runner: Runner
    hdl_top: str

    @classmethod
    def setup_class(cls):
        COREX_ROOT = Path(__file__).parent.parent.parent
        hdl_dir = COREX_ROOT / "hdl_sv" / "core"

        sources = [
            hdl_dir / "control_unit.sv",
            hdl_dir / "ibus_if.sv",
            hdl_dir / "dbus_if.sv",
            hdl_dir / "imem.sv",
            hdl_dir / "dmem.sv",
            hdl_dir / "reg_file.sv",
            hdl_dir / "pipeline_reg.sv",
            hdl_dir / "decoder.sv",
            hdl_dir / "ALU.sv",
            hdl_dir / "execute.sv",
            hdl_dir / "ifu.sv",
            hdl_dir / "core.sv",
        ]

        cls.hdl_top = "CoreTop"
        cls.runner = setup_runner(sources=sources, hdl_toplevel=cls.hdl_top)

    def test_c_func_call(self):
        self.runner.test(
            hdl_toplevel=self.hdl_top,
            test_module=f"testcases.{Path(__file__).stem}",
            testcase="t_core_c_func_call_test",
        )